/* Shared demo state and active-time event queue. Pure model also runs in tests. */
(function(root){
  const Data=typeof module!=='undefined'&&module.exports?require('./data.js'):root.PhoneBridgerData;
  function create(){
    let d=Data.seed(),seq=1000,time=0;const listeners=new Set(),queue=[];
    const uid=p=>`${p}-${++seq}`,contact=id=>d.contacts.find(c=>c.id===id),file=id=>d.files.find(f=>f.id===id);
    function emit(topic='change'){listeners.forEach(fn=>fn(topic));}
    function schedule(key,delay,fn){if(queue.some(e=>e.key===key))return;queue.push({key,due:time+delay,fn});}
    function cancel(key){for(let i=queue.length-1;i>=0;i--)if(queue[i].key===key||queue[i].key.startsWith(key+':'))queue.splice(i,1);}
    function notification(app,title,text,target){const item={id:uid('notification'),app,title,text,target,read:false};d.notifications.unshift(item);d.notifications=d.notifications.slice(0,30);emit('notification');return item;}
    const stamp=()=>{const minutes=615+Math.floor(time/60000);return `${Math.floor(minutes/60)%24}:${String(minutes%60).padStart(2,'0')}`;};
    function receive(thread,text,attachment=null,sender=null){const t=d.threads.find(t=>t.id===thread);if(!t)return;d.messages.push({id:uid('msg'),thread,from:sender||t.members.find(id=>id!=='jamie'),text,attachment,at:stamp(),status:'read',reactions:[]});t.typing=false;t.unread++;if(!t.muted)notification('whatsapp',t.name,text||'Voice note or file',{thread});emit('chat');}
    function start(){if(d.started)return;d.started=true;schedule('intro',9000,()=>receive('alex','Hi Jamie! Could you send the project proposal by email? It is in Drive → Team project.'));schedule('photo-request',45000,()=>receive('mia','I have a photo for the design review. Which one should we use?','photo-studio-detail'));schedule('group-request',95000,()=>receive('group-1','The weekly review is coming up. Feel free to share a note or file here.'));emit('activity');}
    function sendMessage(thread,text,attachment=null,replyTo=null){text=String(text).trim().slice(0,2000);if(!text&&!attachment)return null;const t=d.threads.find(t=>t.id===thread);if(!t)return null;const msg={id:uid('msg'),thread,from:'jamie',text,attachment,replyTo,at:stamp(),status:'sending',reactions:[]};d.messages.push(msg);t.unread=0;start();schedule(msg.id+':delivered',700,()=>{msg.status='delivered';t.typing=true;emit('chat');});schedule(msg.id+':reply',2600+Math.min(text.length*8,2000),()=>{msg.status='read';let reply=attachment?'Thanks, I have the file. I’ll take a look and share it with the team.':/\b(hello|hi|morning)\b/i.test(text)?'Hi Jamie! Good to hear from you. How is the project going?':/proposal|file|send|email/i.test(text)?'Great. Please send the proposal by email when you are ready. I’ll reply in the same thread.':/where|find/i.test(text)?'You can find the proposal in Drive → Team project, then download it to Files.':/meeting|review/i.test(text)?'That works for me. Tuesday at 10:00 is good for the review.':/thank|perfect|great|yes/i.test(text)?'You’re welcome! Let me know if you need anything else for the next step.':'Thanks for the update. Let’s include that in our project review. What would you like to do next?';receive(thread,reply);if(t.group&&attachment)schedule(msg.id+':group-reply',1600,()=>receive(thread,'This one works well for the review. Thanks for sharing it.',null,t.members.filter(id=>id!=='jamie')[1]));if(text.includes('demo://article-')&&!d.scenario.meeting){d.scenario.meeting=true;schedule('article-invitation',7000,()=>{d.mail.push({id:uid('mail'),thread:uid('mail-thread'),from:'alex',to:'jamie',subject:'Let’s discuss your article',text:'Hi Jamie,\n\nThe article you shared raises some useful ideas. Let’s discuss it at our weekly planning meeting on Tuesday at 10:00.\n\nAlex',folder:'inbox',at:stamp(),read:false,star:false,attachments:[],invite:true});notification('gmail','Alex','New meeting invitation',{thread:d.mail.at(-1).thread});emit('mail');});}});emit('chat');return msg;}
    function readThread(id){const t=d.threads.find(t=>t.id===id);if(t){const changed=t.unread>0;t.unread=0;d.notifications.filter(n=>n.app==='whatsapp'&&n.target?.thread===id).forEach(n=>n.read=true);if(changed)emit('read');}}
    function newDraft(fields={}){const draft={id:uid('draft'),to:'',subject:'',text:'',attachments:[],...fields};d.drafts.push(draft);emit('mail');return draft;}
    function saveDraft(id,fields){const draft=d.drafts.find(x=>x.id===id);if(draft)Object.assign(draft,fields);}
    function sendMail(id){const draft=d.drafts.find(x=>x.id===id);if(!draft)return {error:'Draft not found.'};const recipient=contact(draft.to)||d.contacts.find(c=>c.email===draft.to);if(!recipient)return {error:'Choose a contact or enter a demo contact email address.'};if(!draft.text.trim()&&!draft.attachments.length)return {error:'Write a message or attach a file before sending.'};const email={...draft,id:uid('mail'),thread:draft.thread||uid('mail-thread'),from:'jamie',to:recipient.id,subject:draft.subject.trim()||'(No subject)',folder:'sent',at:stamp(),read:true,star:false,undo:true};d.mail.push(email);d.drafts=d.drafts.filter(x=>x.id!==id);start();schedule(email.id+':commit',5000,()=>{email.undo=false;emit('mail');});schedule(email.id+':reply',11000,()=>{d.mail.push({id:uid('mail'),thread:email.thread,from:recipient.id,to:'jamie',subject:email.subject,text:`Hi Jamie,\n\n${email.attachments.length?'Thanks for sending the files. I have received them and will review them with the team.':'Thanks for your message. Let’s include this in our next project review.'}\n\nBest,\n${recipient.name}`,folder:'inbox',at:stamp(),read:false,star:false,attachments:[]});notification('gmail',recipient.name,`Re: ${email.subject}`,{thread:email.thread});if(email.attachments.includes('doc-1')){d.scenario.proposal=true;receive('alex','The proposal arrived by email. Thanks, Jamie — everything is ready for our review.');}emit('mail');});emit('mail');return {email};}
    function undoMail(id){const mail=d.mail.find(m=>m.id===id);if(!mail?.undo)return null;cancel(id);d.mail=d.mail.filter(m=>m.id!==id);const draft=newDraft({to:mail.to,subject:mail.subject,text:mail.text,attachments:[...mail.attachments],thread:mail.thread});emit('mail');return draft;}
    function mailAction(thread,action){const items=d.mail.filter(m=>m.thread===thread),star=!items.some(m=>m.star);if(action==='read')d.notifications.filter(n=>n.app==='gmail'&&n.target?.thread===thread).forEach(n=>n.read=true);items.forEach(m=>{if(action==='star')m.star=star;else if(action==='read')m.read=true;else if(action==='unread')m.read=false;else if(action==='delete'){m.previousFolder=m.folder;m.folder='trash';}else if(action==='restore')m.folder=m.previousFolder||'inbox';else if(action==='archive')m.folder='archive';});emit('mail');}
    function localFiles(where,folder=null){return d.copies.filter(c=>c.where===where&&!c.deleted&&(folder===null||c.folder===folder)).map(c=>({...file(c.file),...c}));}
    function addCopy(id,where,folder,mode='ask',name=null){const f=file(id);if(!f)return {error:'File not found.'};name=name||f.name;const exists=d.copies.find(c=>!c.deleted&&c.where===where&&c.folder===folder&&c.name===name);if(exists&&mode==='ask')return {conflict:exists};if(exists&&mode==='replace'){exists.file=id;exists.modified=stamp();emit('files');return {copy:exists};}if(exists){const dot=name.lastIndexOf('.');let n=2;const make=()=>dot>0?`${name.slice(0,dot)} (${n})${name.slice(dot)}`:`${name} (${n})`;let other=make();while(d.copies.some(c=>!c.deleted&&c.where===where&&c.folder===folder&&c.name===other)){n++;other=make();}name=other;}const copy={id:uid('copy'),file:id,where,folder,name,deleted:false,modified:stamp()};d.copies.push(copy);emit('files');return {copy};}
    function transfer(ids,from,to,folder,mode='ask'){ids=[...new Set(ids)].filter(id=>file(id));if(!ids.length)return null;const existing=d.transfers.find(t=>['queued','running','paused','conflict'].includes(t.status)&&t.from===from&&t.to===to&&t.folder===folder&&t.files.join('|')===ids.join('|'));if(existing)return existing;const item={id:uid('transfer'),files:ids,from,to,folder,mode,progress:0,status:'queued',index:0};d.transfers.push(item);emit('transfer');return item;}
    function transferAction(id,action,mode=null){const t=d.transfers.find(t=>t.id===id);if(!t)return;if(action==='cancel')t.status='cancelled';if(action==='pause'&&['queued','running'].includes(t.status))t.status='paused';if(action==='resume'&&['paused','conflict'].includes(t.status)){if(mode)t.mode=mode;t.status='queued';}emit('transfer');}
    function tick(ms,active=true){if(!active||d.quiet)return;time+=ms;if(d.started){const due=queue.filter(e=>e.due<=time);due.forEach(e=>{const i=queue.indexOf(e);if(i>=0)queue.splice(i,1);e.fn();});}const running=d.transfers.find(t=>['running','queued'].includes(t.status));if(running){running.status='running';running.progress=Math.min(100,running.progress+ms/40);if(running.progress===100){const conflicts=running.files.filter(id=>{const name=file(id)?.name;return d.copies.some(c=>!c.deleted&&c.where===running.to&&c.folder===running.folder&&c.name===name);});if(conflicts.length&&running.mode==='ask'){running.status='conflict';running.conflicts=conflicts;}else{running.files.forEach(id=>addCopy(id,running.to,running.folder,running.mode));running.status='complete';notification('files','Transfer complete',`${running.files.length} file${running.files.length===1?'':'s'} → ${running.to==='pc'?'This PC':running.to==='drive'?'Drive':running.to+' phone'}`,{where:running.to,folder:running.folder});}}emit('transfer');}}
    const undo=[],redo=[];
    function cell(sheetId,wsId,row,col,value,record=true){const s=d.sheets.find(s=>s.id===sheetId),ws=s?.worksheets.find(w=>w.id===wsId);if(!ws)return;while(ws.cells.length<=row)ws.cells.push([]);s.modified=time;const prev=ws.cells[row][col]||'';ws.cells[row][col]=String(value).slice(0,500);if(record){undo.push({sheetId,wsId,row,col,prev,value:String(value)});redo.length=0;}emit('sheet');}
    function sheetHistory(direction){const from=direction==='undo'?undo:redo,to=direction==='undo'?redo:undo,item=from.pop();if(item){to.push(item);cell(item.sheetId,item.wsId,item.row,item.col,direction==='undo'?item.prev:item.value,false);}}
    function formula(ws,row,col,seen=new Set()){const key=`${row}:${col}`;if(seen.has(key))return '#CYCLE!';const value=ws.cells[row]?.[col]||'';if(!String(value).startsWith('='))return value;seen=new Set(seen).add(key);const ref=/^=([A-Z]+)(\d+)$/i.exec(value);const index=letters=>[...letters.toUpperCase()].reduce((n,c)=>n*26+c.charCodeAt(0)-64,0)-1;if(ref)return formula(ws,Number(ref[2])-1,index(ref[1]),seen);const match=/^=(SUM|AVERAGE|COUNT)\(([A-Z]+)(\d+):([A-Z]+)(\d+)\)$/i.exec(value);if(!match)return '#ERROR!';const startRow=Number(match[3])-1,endRow=Number(match[5]),startCol=index(match[2]),endCol=index(match[4]);if(startRow<0||endRow<=startRow||endCol<startCol||(endRow-startRow)*(endCol-startCol+1)>10000)return '#RANGE!';const values=[];for(let r=Number(match[3])-1;r<Number(match[5]);r++)for(let c=index(match[2]);c<=index(match[4]);c++){const v=formula(ws,r,c,seen);if(typeof v==='string'&&v.startsWith('#'))return v;if(v!==''&&Number.isFinite(Number(v)))values.push(Number(v));}const sum=values.reduce((a,b)=>a+b,0);return match[1].toUpperCase()==='COUNT'?values.length:match[1].toUpperCase()==='AVERAGE'?(values.length?sum/values.length:0):sum;}
    function reset(){d=Data.seed();seq=1000;time=0;queue.length=0;undo.length=redo.length=0;emit('reset');}
    return {get data(){return d;},uid,contact,file,subscribe(fn){listeners.add(fn);return()=>listeners.delete(fn);},emit,start,tick,schedule,cancel,notification,sendMessage,readThread,newDraft,saveDraft,sendMail,undoMail,mailAction,localFiles,addCopy,transfer,transferAction,cell,sheetHistory,formula,reset,get pending(){return queue.length;},get clock(){return stamp();}};
  }
  const api={create};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.PhoneBridgerState=api;
})(typeof window!=='undefined'?window:globalThis);
